using System.Runtime.InteropServices;

namespace Leo.App;

/// <summary>The LEO mark (yellow face with glasses) — Assets/leo.ico, generated by tools/make-icon.ps1.</summary>
internal static class AppIcons
{
    public static string IcoPath { get; } = Path.Combine(AppContext.BaseDirectory, "Assets", "leo.ico");

    /// <summary>Picks the tray-sized frame (16 px at 100 %, 24 px at 150 %, …) so it isn't blurry.</summary>
    public static System.Drawing.Icon LoadTrayIcon()
    {
        var size = GetSystemMetrics(SmCxSmIcon);
        if (size <= 0) size = 16;
        return new System.Drawing.Icon(IcoPath, size, size);
    }

    private const int SmCxSmIcon = 49;

    [DllImport("user32.dll")]
    private static extern int GetSystemMetrics(int index);
}
